-- Run after fix-services-catalog.sql. Safe to run repeatedly.
on conflict (slug) do update set
  name = excluded.name, category = excluded.category, description = excluded.description, price = excluded.price, delivery = excluded.delivery, icon = excluded.icon, popular = excluded.popular, included = excluded.included, technologies = excluded.technologies,
  is_active = case when public.service_catalog.slug = 'business-website' then false else public.service_catalog.is_active end, sort_order = excluded.sort_order, updated_at = now();
